insert into chapters(slug,title,description,year_from,year_to,sort_order)values('acute','Acute Cardiac Care','ACS, tamponade, stuck mechanical prosthesis, cardiac arrest, VT, AF, temporary pacing, aortic dissection, pneumothorax and stroke.',1,1,10),('cad','Coronary Artery Disease','Diagnosis, investigation, evidence-based management and secondary prevention.',1,1,20),('hf','Heart Failure','Acute and chronic heart failure assessment and treatment.',1,1,30),('valves','Valvular Heart Disease','Native and prosthetic valve assessment and management.',2,2,10),('tte','Transthoracic Echocardiography','Systematic adult TTE acquisition and interpretation.',2,2,20),('arrhythmias','Advanced Arrhythmias','Advanced rhythm diagnosis, monitoring and treatment.',2,2,30),('rehab','Cardiac Rehabilitation','Risk assessment, exercise prescription and secondary prevention.',3,3,10),('oncology','Cardio-Oncology','Cardiovascular prevention and care during cancer therapy.',3,3,20),('pregnancy','Cardio-Pregnancy','Pre-conception, pregnancy, delivery and postpartum care.',3,3,30),('ncs','Non-Cardiac Surgery','Perioperative cardiovascular assessment and care.',3,3,40),('cm','Cardiomyopathies','Phenotyping, genetics, risk stratification and treatment.',3,3,50),('achd','Adult Congenital Heart Disease','Recognition and structured adult congenital care.',3,3,60),('angiography','Coronary Angiography','Access, anatomy, acquisition, interpretation and safety.',3,3,70),('tee','Transesophageal Echocardiography','Safe systematic diagnostic TEE.',4,5,10),('pci','Simple PCI','Planning and performance of straightforward PCI.',4,5,20),('ppm','Permanent Pacemaker','Indication, implantation, testing and follow-up.',4,5,30)on conflict(slug)do update set title=excluded.title,description=excluded.description;
insert into knowledge_items(chapter_id,title,description,sort_order)select id,'Core knowledge: '||title,description,10 from chapters on conflict do nothing;insert into knowledge_items(chapter_id,title,description,sort_order)select id,'Guidelines and clinical decision-making','Apply current evidence, risk assessment, escalation and follow-up.',20 from chapters on conflict do nothing;
insert into skills(chapter_id,title,description,expected_level,sort_order)select id,'Structured clinical assessment','Perform a safe, systematic assessment appropriate to this chapter.',3,10 from chapters on conflict do nothing;insert into skills(chapter_id,title,description,expected_level,sort_order)select id,'Investigation and management plan','Interpret key investigations and formulate an evidence-based plan.',3,20 from chapters on conflict do nothing;
insert into assessment_deduction_reasons(domain,code,label,sort_order)values('knowledge','K1','Important diagnostic or differential diagnosis gap',10),('knowledge','K2','Does not apply current evidence-based management',20),('knowledge','K3','Unsafe medication, risk, or escalation knowledge',30),('skills','S1','Clinical examination or ECG skill below expected level',10),('skills','S2','Technical sequence, preparation, or asepsis incomplete',20),('skills','S3','Does not anticipate or manage complications safely',30),('attitude','A1','Communication with seniors or colleagues needs improvement',10),('attitude','A2','Communication with nurses or patients needs improvement',20),('attitude','A3','Accountability, reliability, or response to feedback inadequate',30)on conflict(code)do update set label=excluded.label;commit;
